import type { Account, Iso, Observation } from "@/lib/signals/types";
import { accountSchema, observationSchema } from "@/lib/watchlist/schema";

import accountsJson from "./accounts.json";
import observationsJson from "./observations.json";

/**
 * The bundled dataset, parsed through Zod **at import time**. A bad hand-edit to
 * either JSON file therefore fails the build rather than the first request that
 * happens to touch the affected account.
 *
 * Both files are generated by `npm run generate:dataset`; edit the recipe in
 * `scripts/generate-dataset.mts` rather than the JSON, or the next regeneration
 * silently discards the change.
 */

export const ACCOUNTS: Account[] = accountSchema.array().parse(accountsJson);
export const OBSERVATIONS: Observation[] = observationSchema.array().parse(observationsJson);

/** Every crawl date present in the dataset, ascending. Drives the scrubber's bounds. */
export const CRAWL_DATES: Iso[] = [
  ...new Set(OBSERVATIONS.map((observation) => observation.observed_at)),
].sort();

function boundary(index: number): Iso {
  const date = CRAWL_DATES[index];
  if (date === undefined) throw new Error("dataset has no observations");
  return date;
}

export const FIRST_CRAWL: Iso = boundary(0);
export const LAST_CRAWL: Iso = boundary(CRAWL_DATES.length - 1);

/** The board opens at the most recent crawl — the state of the world as last seen. */
export const DEFAULT_AS_OF: Iso = LAST_CRAWL;

/**
 * Tool-name suggestions for the watchlist editor's `<datalist>`, derived from the
 * **raw JSON** rather than the parsed export. That is deliberate: importing this
 * from a client component must not pull Zod into the browser bundle.
 */
export const STACK_VOCABULARY: string[] = [
  ...new Set(
    (observationsJson as { state: { stack: string[] } }[]).flatMap(
      (observation) => observation.state.stack,
    ),
  ),
].sort();
